import{_ as i,C as o,o as e,c as n,a2 as a,b as d,w as r,a as l,E as c,a3 as u}from"./chunks/framework.XaTYfhfj.js";const S=JSON.parse('{"title":"14.5 Databases, Persistent Storage & Evidentiary Custody","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/14.5-databases-and-storage.md","filePath":"system-design/14.5-databases-and-storage.md"}'),g={name:"system-design/14.5-databases-and-storage.md"};function h(p,t,m,b,y,A){const s=o("Mermaid");return e(),n("div",null,[t[1]||(t[1]=a('<h1 id="_14-5-databases-persistent-storage-evidentiary-custody" tabindex="-1">14.5 Databases, Persistent Storage &amp; Evidentiary Custody <a class="header-anchor" href="#_14-5-databases-persistent-storage-evidentiary-custody" aria-label="Permalink to &quot;14.5 Databases, Persistent Storage &amp; Evidentiary Custody&quot;">​</a></h1><h2 id="_1-what-it-is-in-plain-words" tabindex="-1">1. What It Is in Plain Words <a class="header-anchor" href="#_1-what-it-is-in-plain-words" aria-label="Permalink to &quot;1. What It Is in Plain Words&quot;">​</a></h2><p>Database and storage architecture determines how an application persists, indexes, retrieves, and protects data over time. In digital forensics, storage systems must balance structured relational integrity (user permissions, audit trails) with high-capacity immutable object custody (videos, images, binary hashes).</p><hr><h2 id="_2-truthguard-storage-topology" tabindex="-1">2. TruthGuard Storage Topology <a class="header-anchor" href="#_2-truthguard-storage-topology" aria-label="Permalink to &quot;2. TruthGuard Storage Topology&quot;">​</a></h2>',5)),(e(),d(u,null,{default:r(()=>[c(s,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20subgraph%20ClientStorage%20%5B%22Client%20Browser%20Storage%22%5D%0A%20%20%20%20%20%20%20%20LocalStorage%5B%22localStorage%3A%20mediavault_files%20(Max%205MB)%22%5D%0A%20%20%20%20%20%20%20%20IndexedDB%5B%22Planned%20IndexedDB%3A%20Multi-Gigabyte%20Offline%20Evidence%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20RelationalDB%20%5B%22Cloud%20Database%3A%20PostgreSQL%20(Supabase)%22%5D%0A%20%20%20%20%20%20%20%20ProfilesTable%5B(%22public.profiles%3A%20User%20Roles%20%26%20Attributes%22)%5D%0A%20%20%20%20%20%20%20%20AuthUsers%5B(%22auth.users%3A%20Credentials%20%26%20Salted%20Hashes%22)%5D%0A%20%20%20%20%20%20%20%20IncidentsTable%5B(%22Planned%20incidents%3A%20Case%20Records%20%26%20Metadata%22)%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20ObjectCustody%20%5B%22Evidence%20Object%20Storage%20(Planned%20Enterprise%20Tier)%22%5D%0A%20%20%20%20%20%20%20%20S3Bucket%5B(%22AWS%20S3%20%2F%20Supabase%20Storage%3A%20Media%20Blobs%22)%5D%0A%20%20%20%20%20%20%20%20WORM%5B%22Object%20Lock%20(WORM%3A%20Write%20Once%2C%20Read%20Many)%22%5D%0A%20%20%20%20%20%20%20%20S3Bucket%20---%20WORM%0A%20%20%20%20end%0A%0A%20%20%20%20ClientStorage%20-.-%3E%7CCustody%20Sync%7C%20S3Bucket%0A%20%20%20%20ProfilesTable%20%3C--%3E%7CForeign%20Key%3A%20user_id%7C%20AuthUsers%0A"})]),fallback:r(()=>[...t[0]||(t[0]=[l(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=a('<hr><h2 id="_3-database-engine-comparison-matrix" tabindex="-1">3. Database Engine Comparison Matrix <a class="header-anchor" href="#_3-database-engine-comparison-matrix" aria-label="Permalink to &quot;3. Database Engine Comparison Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Engine</th><th>Data Model</th><th>ACID Compliance</th><th>Horizontal Scaling</th><th>Query Language</th><th>Best Use in TruthGuard</th></tr></thead><tbody><tr><td><strong>PostgreSQL (Chosen)</strong></td><td>Relational</td><td><strong>Full (Strict)</strong></td><td>Read Replicas</td><td>SQL</td><td><strong>Profiles, Audit Logs, Case Integrity</strong></td></tr><tr><td><strong>MongoDB</strong></td><td>Document JSON</td><td>Document-level</td><td>Native Sharding</td><td>MQL</td><td>Good for flexible incident logs</td></tr><tr><td><strong>DynamoDB</strong></td><td>Key-Value / Doc</td><td>Eventual / Strong</td><td>Native Auto-scale</td><td>Dynamo API</td><td>High-throughput sensor streams</td></tr><tr><td><strong>CockroachDB</strong></td><td>Distributed SQL</td><td>Full (Serializable)</td><td>Native Multi-Master</td><td>SQL</td><td>Multi-region global compliance</td></tr><tr><td><strong>Redis</strong></td><td>In-Memory K-V</td><td>Minimal (RDB/AOF)</td><td>Cluster Sharding</td><td>Redis Commands</td><td>Deduplication &amp; Semantic Cache</td></tr><tr><td><strong>IndexedDB</strong></td><td>In-Browser NoSQL</td><td>Transactional</td><td>Local Machine</td><td>JS Cursor API</td><td>Large client evidence storage</td></tr></tbody></table><hr><h2 id="_4-cap-pacelc-theorem-evaluation" tabindex="-1">4. CAP &amp; PACELC Theorem Evaluation <a class="header-anchor" href="#_4-cap-pacelc-theorem-evaluation" aria-label="Permalink to &quot;4. CAP &amp; PACELC Theorem Evaluation&quot;">​</a></h2><p>TruthGuard’s relational data sits squarely as a <strong>CP system</strong> (Consistency over Availability during network partitions) under the CAP theorem:</p><ul><li><strong>Consistency Priority</strong>: In a forensic cyber-defense system, having two analysts observe conflicting role definitions or divergent audit timestamps is unacceptable. PostgreSQL enforces strong serializability and immediate consistency.</li><li><strong>PACELC Classification</strong>: Under the PACELC theorem, TruthGuard is <strong>PC/EC</strong> (Partition: Consistency over Availability; Else: Consistency over Latency). The platform prioritizes exact evidentiary accuracy over millisecond response latency.</li></ul><hr><h2 id="_5-30-second-spoken-interview-answer" tabindex="-1">5. 30-Second Spoken Interview Answer <a class="header-anchor" href="#_5-30-second-spoken-interview-answer" aria-label="Permalink to &quot;5. 30-Second Spoken Interview Answer&quot;">​</a></h2><blockquote><p>&quot;For persistent storage, TruthGuard pairs PostgreSQL for structured relational data with client-side storage for active evidence. We chose PostgreSQL because digital forensics requires strict ACID guarantees and Row Level Security to protect analyst profiles and evidence custody trails.</p><p>Under the CAP theorem, we deliberately prioritize Consistency over Availability (CP) because evidentiary records can never allow dirty reads or split-brain inconsistencies.&quot;</p></blockquote>',10))])}const _=i(g,[["render",h]]);export{S as __pageData,_ as default};
